package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取两个字符串
    line1, _ := reader.ReadString('\n')
    line2, _ := reader.ReadString('\n')
    input1 := strings.TrimSpace(line1)
    input2 := strings.TrimSpace(line2)
​
    len1 := len(input1)
    len2 := len(input2)
    res := 0
​
    // dp[i][j] 表示以 input1[i-1] 和 input2[j-1] 结尾的最长公共子串长度
    dp := make([][]int, len1+1)
    for i := range dp {
        dp[i] = make([]int, len2+1)
    }
​
    for i := 1; i <= len1; i++ {
        for j := 1; j <= len2; j++ {
            if input1[i-1] == input2[j-1] {
                dp[i][j] = dp[i-1][j-1] + 1
                res = max(res, dp[i][j])
            }
        }
    }
​
    fmt.Println(res)
}
